#include <stdio.h>

char P[100005];
int N;

int check(int L) {
    int target[26] = {0};
    for (int i = 0; i < L; i++) {
        target[P[i] - 'a']++;
    }

    int blocks = N / L;
    for (int b = 1; b < blocks; b++) {
        int freq[26] = {0};
        int start = b * L;
        for (int i = start; i < start + L; i++) {
            freq[P[i] - 'a']++;
        }

        for (int c = 0; c < 26; c++) {
            if (freq[c] != target[c]) {
                return 0;
            }
        }
    }

    return 1;
}

int main() {
    scanf("%d", &N);
    scanf("%s", P);

    for (int L = 1; L <= N / 2; L++) {
        if (N % L == 0 && check(L)) {
            for (int i = 0; i < L; i++) {
                putchar(P[i]);
            }
            putchar('\n');
            return 0;
        }
    }

    printf("*\n");
    return 0;
}
