#include <stdio.h>

int main() {
    int N;
    char P[100005];
    scanf("%d", &N);
    scanf("%s", P);

    for (int L = 1; L <= N / 2; ++L) {
        if (N % L != 0) continue;

        int cnt[26] = {0};
        for (int i = 0; i < L; ++i) {
            cnt[P[i] - 'a']++;
        }

        int ok = 1;
        for (int start = L; start < N; start += L) {
            int tmp[26] = {0};
            for (int i = 0; i < L; ++i) {
                tmp[P[start + i] - 'a']++;
            }

            for (int c = 0; c < 26; ++c) {
                if (tmp[c] != cnt[c]) {
                    ok = 0;
                    break;
                }
            }
            if (!ok) break;
        }

        if (ok) {
            printf("%.*s\n", L, P);
            return 0;
        }
    }

    printf("*\n");
    return 0;
}
